import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('SpaceGrotesk');

// Module-level font loading
const { fontFamily } = loadFont();



export type PriceUpdateProps = Record<string, any>;

const PriceUpdate: React.FC<PriceUpdateProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 5,
  initialAmount = 800,
  finalAmount = 3800,
  currencySymbol = "$",
  primaryColor = "#ffffff",
  accentColor = "#22c55e",
  strikethroughColor = "#ef4444",
}) => {
  const frame = useCurrentFrame();
  const { fps, height } = useVideoConfig();

  // Parser Safety
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Sequence Timings
  const tallyDuration = fps * 1.5; // Starts at 0, ends at 1.5s
  const strikeStart = tallyDuration + fps * 0.5; // Starts at 2.0s
  const shiftStart = strikeStart + fps * 0.5; // Starts at 2.5s
  const revealStart = shiftStart + fps * 0.15; // Starts at 2.65s

  // 1. Tally Animation
  const tallySpring = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 40 },
  });
  const displayAmount = Math.round(
    interpolate(tallySpring, [0, 1], [0, initialAmount])
  );

  // 2. Strikethrough Animation
  const strikeSpring = spring({
    frame: frame - strikeStart,
    fps,
    config: { damping: 12, stiffness: 80, mass: 0.8 },
  });
  const strikeWidth = interpolate(strikeSpring, [0, 1], [0, 110], {
    extrapolateRight: "clamp",
  });

  // 3. Shift Container Animation (moves everything up to make room)
  const shiftSpring = spring({
    frame: frame - shiftStart,
    fps,
    config: { damping: 14, stiffness: 60 },
  });
  const containerY = interpolate(shiftSpring, [0, 1], [0, -height * 0.12]);
  const oldAmountOpacity = interpolate(shiftSpring, [0, 1], [1, 0.4]);
  const oldAmountScale = interpolate(shiftSpring, [0, 1], [1, 0.85]);

  // 4. Reveal New Amount Animation
  const revealSpring = spring({
    frame: frame - revealStart,
    fps,
    config: { damping: 10, mass: 1.2, stiffness: 100 },
  });
  const newScale = interpolate(revealSpring, [0, 1], [0.5, 1]);
  const newOpacity = interpolate(revealSpring, [0, 1], [0, 1]);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          transform: `translateY(${containerY}px)`,
          transition: "none",
        }}
      >
        {/* Old Amount */}
        <div
          style={{
            position: "relative",
            display: "inline-block",
            opacity: oldAmountOpacity,
            transform: `scale(${oldAmountScale})`,
            transition: "none",
          }}
        >
          <span
            style={{
              fontSize: 180,
              fontWeight: 700,
              color: primaryColor,
              letterSpacing: "-0.02em",
              transition: "none",
            }}
          >
            {currencySymbol}
            {displayAmount.toLocaleString()}
          </span>

          {/* Strikethrough Line */}
          <div
            style={{
              position: "absolute",
              top: "50%",
              left: "-5%",
              width: `${strikeWidth}%`,
              height: 20,
              backgroundColor: strikethroughColor,
              transform: "translateY(-50%) rotate(-4deg)",
              transformOrigin: "left center",
              borderRadius: 10,
              boxShadow: `0px 4px 15px ${strikethroughColor}60`,
              transition: "none",
            }}
          />
        </div>

        {/* New Amount */}
        <div
          style={{
            marginTop: 40,
            opacity: newOpacity,
            transform: `scale(${newScale})`,
            transition: "none",
          }}
        >
          <span
            style={{
              fontSize: 260,
              fontWeight: 800,
              color: accentColor,
              letterSpacing: "-0.03em",
              textShadow: `0px 10px 40px ${accentColor}50`,
              transition: "none",
            }}
          >
            {currencySymbol}
            {finalAmount.toLocaleString()}
          </span>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default PriceUpdate;